def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_actions = [h[1] for h in history]
    opp_c = opp_actions.count('C')
    opp_coop_rate = opp_c / n
    last_opp = opp_actions[-1]
    remaining = 100 - n

    # Endgame: defect in last few rounds based on opponent's cooperation rate
    if remaining <= 1:
        return 'D'
    if remaining <= 5 and opp_coop_rate < 0.9:
        return 'D'
    if remaining <= 10 and opp_coop_rate < 0.85:
        return 'D'
    if remaining <= 15 and opp_coop_rate < 0.8:
        return 'D'

    # Early test: if opponent has been perfectly cooperative for 8 rounds, test with D on round 9
    if n == 8 and opp_c == 8:
        return 'D'

    # If opponent is very cooperative and we are not near the end, forgive defections
    if remaining > 15 and opp_coop_rate > 0.9:
        return 'C'

    # If opponent is very defective, defect
    if opp_coop_rate < 0.3:
        return 'D'

    # TFT with forgiveness
    if last_opp == 'D':
        # Count consecutive defections at the end
        streak = 0
        for a in reversed(opp_actions):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 2:
            return 'D'
        # Single defection: forgive if opponent is generally cooperative and not near end
        if remaining > 15 and opp_coop_rate > 0.7:
            return 'C'
        return 'D'
    else:
        return 'C'
